results=[]
for k in range(8):
    for d in [True, False]:
        # feasibility: director from SH requires k>=1; director not from SH requires k<=6
        if d and k<1: continue
        if (not d) and k>=7: continue
        I = k>=1
        II = k<7
        III = not d
        if [I,II,III].count(True)==1:
            results.append((k,d,(I,II,III)))
